create table public.project_images(id uuid primary key,user_id uuid not null references public.profiles(id)on delete cascade,project_id uuid not null references public.projects(id)on delete cascade,path text not null check(path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.png$'),created_at timestamptz not null default now());
alter table public.project_images enable row level security;revoke all on public.project_images from public,anon,authenticated;grant select on public.project_images to authenticated;grant all on public.project_images to service_role;
create policy project_images_read on public.project_images for select to authenticated using(private.member()and private.project_read(project_id)and exists(select 1 from public.project_members m where m.project_id=project_images.project_id and m.user_id=auth.uid()));
create function public.project_image_budget(pid uuid)returns void language plpgsql security definer set search_path=''as $$begin if not private.member()or not private.project_read(pid)or not exists(select 1 from public.project_members where project_id=pid and user_id=auth.uid())then raise insufficient_privilege;end if;perform private.rate_limit('project_image',3);end$$;
revoke all on function public.project_image_budget(uuid)from public,anon;grant execute on function public.project_image_budget(uuid)to authenticated;
